CREATE TABLE merchant_payment_methods(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),merchant_id UUID REFERENCES merchants(id),branch_id UUID REFERENCES branches(id),payment_method VARCHAR(30) NOT NULL,provider VARCHAR(40) NOT NULL,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,merchant_id,branch_id,payment_method),CHECK(payment_method IN('CASH_ON_DELIVERY','CARD','DIGITAL_WALLET','BANK_TRANSFER','OTHER')));
CREATE TABLE payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),order_id UUID NOT NULL REFERENCES orders(id),customer_id UUID NOT NULL REFERENCES users(id),merchant_id UUID NOT NULL REFERENCES merchants(id),payment_method VARCHAR(30) NOT NULL,provider VARCHAR(40) NOT NULL,status VARCHAR(30) NOT NULL,currency VARCHAR(3) NOT NULL,amount NUMERIC(12,2) NOT NULL,authorized_amount NUMERIC(12,2) NOT NULL DEFAULT 0,captured_amount NUMERIC(12,2) NOT NULL DEFAULT 0,refunded_amount NUMERIC(12,2) NOT NULL DEFAULT 0,provider_payment_id VARCHAR(160),provider_reference VARCHAR(160),failure_code VARCHAR(80),failure_message VARCHAR(255),idempotency_key VARCHAR(160) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),authorized_at TIMESTAMPTZ,captured_at TIMESTAMPTZ,cancelled_at TIMESTAMPTZ,UNIQUE(tenant_id,idempotency_key),CHECK(status IN('PENDING','PROCESSING','AUTHORIZED','PAID','FAILED','CANCELLED','PARTIALLY_REFUNDED','REFUNDED','EXPIRED')),CHECK(amount>0 AND authorized_amount>=0 AND captured_amount>=0 AND refunded_amount>=0));
CREATE INDEX idx_payments_tenant_created ON payments(tenant_id,created_at DESC);CREATE INDEX idx_payments_order ON payments(tenant_id,order_id);CREATE INDEX idx_payments_status ON payments(tenant_id,status);
CREATE TABLE payment_attempts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),payment_id UUID NOT NULL REFERENCES payments(id) ON DELETE CASCADE,attempt_number INTEGER NOT NULL,request_reference VARCHAR(160) NOT NULL,provider VARCHAR(40) NOT NULL,status VARCHAR(30) NOT NULL,amount NUMERIC(12,2) NOT NULL,failure_code VARCHAR(80),failure_message VARCHAR(255),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ,UNIQUE(payment_id,attempt_number));
CREATE TABLE payment_transactions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),payment_id UUID NOT NULL REFERENCES payments(id) ON DELETE CASCADE,transaction_type VARCHAR(30) NOT NULL,provider_transaction_id VARCHAR(160),amount NUMERIC(12,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(30) NOT NULL,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(transaction_type IN('AUTHORIZATION','CAPTURE','SALE','VOID','REFUND','FAILED')));
CREATE TABLE payment_refunds(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),payment_id UUID NOT NULL REFERENCES payments(id),order_id UUID NOT NULL REFERENCES orders(id),amount NUMERIC(12,2) NOT NULL,reason VARCHAR(500) NOT NULL,status VARCHAR(30) NOT NULL,provider_refund_id VARCHAR(160),requested_by UUID NOT NULL REFERENCES users(id),idempotency_key VARCHAR(160) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),processed_at TIMESTAMPTZ,failure_message VARCHAR(255),UNIQUE(tenant_id,idempotency_key),CHECK(amount>0));
CREATE TABLE payment_webhook_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID REFERENCES tenants(id),provider VARCHAR(40) NOT NULL,external_event_id VARCHAR(160) NOT NULL,event_type VARCHAR(100) NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,status VARCHAR(30) NOT NULL DEFAULT 'RECEIVED',received_at TIMESTAMPTZ NOT NULL DEFAULT now(),processed_at TIMESTAMPTZ,failure_message VARCHAR(255),UNIQUE(provider,external_event_id),CHECK(status IN('RECEIVED','PROCESSING','PROCESSED','FAILED','IGNORED')));

CREATE TABLE delivery_zones(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),merchant_id UUID NOT NULL REFERENCES merchants(id),branch_id UUID REFERENCES branches(id),name VARCHAR(160) NOT NULL,description VARCHAR(255),zone_type VARCHAR(30) NOT NULL DEFAULT 'DISTRICT',areas TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,minimum_order_amount NUMERIC(12,2) NOT NULL DEFAULT 0,base_delivery_fee NUMERIC(12,2) NOT NULL DEFAULT 0,currency VARCHAR(3) NOT NULL DEFAULT 'PEN',estimated_minutes INTEGER NOT NULL DEFAULT 30,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(zone_type IN('DISTRICT','CITY','POSTAL_CODE','RADIUS')),CHECK(minimum_order_amount>=0 AND base_delivery_fee>=0));
CREATE INDEX idx_delivery_zones_scope ON delivery_zones(tenant_id,merchant_id,branch_id,active);
CREATE TABLE delivery_rates(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),delivery_zone_id UUID NOT NULL REFERENCES delivery_zones(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,base_fee NUMERIC(12,2) NOT NULL,fee_per_km NUMERIC(12,2) NOT NULL DEFAULT 0,minimum_fee NUMERIC(12,2),maximum_fee NUMERIC(12,2),free_delivery_threshold NUMERIC(12,2),currency VARCHAR(3) NOT NULL,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(base_fee>=0 AND fee_per_km>=0));
CREATE TABLE courier_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),user_id UUID NOT NULL REFERENCES users(id),status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',vehicle_type VARCHAR(20) NOT NULL,phone VARCHAR(40),max_active_deliveries INTEGER NOT NULL DEFAULT 1,current_active_deliveries INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id),CHECK(status IN('ACTIVE','INACTIVE','SUSPENDED')),CHECK(vehicle_type IN('BICYCLE','MOTORCYCLE','CAR','VAN','WALKER','OTHER')),CHECK(max_active_deliveries>0 AND current_active_deliveries>=0));
CREATE TABLE courier_availability(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),courier_id UUID NOT NULL REFERENCES courier_profiles(id) ON DELETE CASCADE,status VARCHAR(20) NOT NULL DEFAULT 'OFFLINE',available_from TIMESTAMPTZ,available_until TIMESTAMPTZ,zone_id UUID REFERENCES delivery_zones(id),branch_id UUID REFERENCES branches(id),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(courier_id),CHECK(status IN('ONLINE','OFFLINE','BUSY','PAUSED')));
CREATE TABLE deliveries(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),order_id UUID NOT NULL REFERENCES orders(id),merchant_id UUID NOT NULL REFERENCES merchants(id),branch_id UUID NOT NULL REFERENCES branches(id),customer_id UUID NOT NULL REFERENCES users(id),courier_id UUID REFERENCES courier_profiles(id),delivery_address_id UUID NOT NULL REFERENCES delivery_addresses(id),address_snapshot JSONB NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',delivery_type VARCHAR(30) NOT NULL,distance_km NUMERIC(8,2),estimated_duration_minutes INTEGER,delivery_fee NUMERIC(12,2) NOT NULL,currency VARCHAR(3) NOT NULL,pickup_notes VARCHAR(500),delivery_notes VARCHAR(500),failure_reason VARCHAR(500),assigned_at TIMESTAMPTZ,accepted_at TIMESTAMPTZ,picked_up_at TIMESTAMPTZ,delivered_at TIMESTAMPTZ,cancelled_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(status IN('PENDING','SEARCHING_COURIER','ASSIGNED','ACCEPTED','ARRIVED_AT_MERCHANT','PICKED_UP','IN_TRANSIT','ARRIVED_AT_CUSTOMER','DELIVERED','FAILED','CANCELLED','REJECTED','EXPIRED')),CHECK(delivery_type IN('MERCHANT_DELIVERY','PLATFORM_DELIVERY','PICKUP')));
CREATE UNIQUE INDEX uq_active_delivery_order ON deliveries(tenant_id,order_id) WHERE status NOT IN('DELIVERED','FAILED','CANCELLED','REJECTED','EXPIRED');CREATE INDEX idx_deliveries_tenant_status ON deliveries(tenant_id,status,created_at DESC);CREATE INDEX idx_deliveries_courier ON deliveries(tenant_id,courier_id,status);
CREATE TABLE delivery_assignments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),delivery_id UUID NOT NULL REFERENCES deliveries(id),courier_id UUID NOT NULL REFERENCES courier_profiles(id),status VARCHAR(20) NOT NULL DEFAULT 'PENDING',assignment_type VARCHAR(20) NOT NULL,assigned_by UUID REFERENCES users(id),idempotency_key VARCHAR(160) NOT NULL,assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(),responded_at TIMESTAMPTZ,expires_at TIMESTAMPTZ,rejection_reason VARCHAR(500),UNIQUE(tenant_id,idempotency_key),CHECK(status IN('PENDING','ACCEPTED','REJECTED','EXPIRED','CANCELLED')),CHECK(assignment_type IN('MANUAL','AUTOMATIC')));
CREATE TABLE delivery_status_history(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),delivery_id UUID NOT NULL REFERENCES deliveries(id) ON DELETE CASCADE,status VARCHAR(30) NOT NULL,actor_id UUID REFERENCES users(id),actor_type VARCHAR(30) NOT NULL,notes VARCHAR(500),old_status VARCHAR(30),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),correlation_id VARCHAR(100));CREATE INDEX idx_delivery_history ON delivery_status_history(tenant_id,delivery_id,created_at);

INSERT INTO permissions(code,module,action,description) VALUES ('PAYMENT_VIEW','PAYMENT','VIEW','Ver pagos'),('PAYMENT_CREATE','PAYMENT','CREATE','Crear pagos'),('PAYMENT_REFUND','PAYMENT','REFUND','Reembolsar pagos'),('PAYMENT_ADMIN','PAYMENT','ADMIN','Administrar pagos'),('DELIVERY_VIEW','DELIVERY','VIEW','Ver entregas'),('DELIVERY_CREATE','DELIVERY','CREATE','Crear entregas'),('DELIVERY_ASSIGN','DELIVERY','ASSIGN','Asignar repartidores'),('DELIVERY_UPDATE_STATUS','DELIVERY','UPDATE_STATUS','Actualizar entregas'),('DELIVERY_CANCEL','DELIVERY','CANCEL','Cancelar entregas'),('DELIVERY_ADMIN','DELIVERY','ADMIN','Administrar entregas'),('COURIER_VIEW','DELIVERY','COURIER_VIEW','Ver repartidores'),('COURIER_MANAGE','DELIVERY','COURIER_MANAGE','Administrar repartidores'),('COURIER_AVAILABILITY_MANAGE','DELIVERY','COURIER_AVAILABILITY','Administrar disponibilidad'),('DELIVERY_ZONE_VIEW','DELIVERY','ZONE_VIEW','Ver zonas'),('DELIVERY_ZONE_MANAGE','DELIVERY','ZONE_MANAGE','Administrar zonas') ON CONFLICT(code) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code IN('TENANT_ADMIN','PLATFORM_ADMIN') AND p.module IN('PAYMENT','DELIVERY') ON CONFLICT DO NOTHING;
